mapper.select:
SELECT job_id, capture_id, bundle_id, status, started_at, finished_at, error, incident_count FROM dashboard.scoring_jobs
AND capture_id = #{captureId}
ORDER BY job_id DESC

SELECT job_id, capture_id, bundle_id, status, started_at, finished_at, error, incident_count
FROM dashboard.scoring_jobs
WHERE job_id = #{jobId}

SELECT bundle_id, registry_name, registry_version, manifest_sha256, registered_at, thresholds
FROM dashboard.model_bundles
WHERE bundle_id = #{bundleId}


WHERE q.job_id = #{jobId}
  AND q.queue_rank = #{queueRank}
LIMIT 1


WHERE q.job_id = #{jobId}
  AND q.incident_id = #{incidentId}
LIMIT 1

SELECT job_id, incident_id, zeekad_model, max_score, candidate_windows, windows
FROM dashboard.incident_model_scores
WHERE job_id = #{jobId}
  AND incident_id = #{incidentId}
ORDER BY zeekad_model ASC

SELECT *
FROM dashboard.asset_names
WHERE capture_id = #{captureId}
  AND host_ip = #{hostIp}

SELECT DISTINCT incident_id
FROM dashboard.slack_deliveries
WHERE TRIM(zeekad_thread_parent) = #{headIncidentId}
ORDER BY incident_id
LIMIT #{limit}

SELECT job_id, capture_id, zeekad_message_version, zeekad_delivery_mode, zeekad_delivery_status, slack_payload, slack_ts, delivered_at, created_at FROM dashboard.slack_summaries
AND capture_id = #{captureId}
ORDER BY created_at DESC, job_id DESC

SELECT * FROM dashboard.feedback_summary
AND capture_id = #{captureId}
ORDER BY capture_id ASC, bundle_id DESC, zeekad_picked_by ASC

SELECT b.*
FROM () b





    LIMIT #{c.limit}

        OFFSET #{c.offset}

WITH w AS ( SELECT b.*, ROW_NUMBER() OVER () AS queue_pos, COUNT(*) OVER () AS queue_total FROM () b
) SELECT w.* FROM w
WHERE ABS(w.queue_pos - ( SELECT cw.queue_pos FROM w cw WHERE cw.job_id = #{jobId} AND cw.queue_rank = #{queueRank} )) <= 1 ORDER BY w.queue_pos

SELECT j.job_id, j.capture_id, j.bundle_id, j.status, j.started_at, j.finished_at, j.error, j.incident_count
FROM dashboard.scoring_jobs j
WHERE j.capture_id IN
  #{cid}

ORDER BY j.job_id DESC

    LIMIT #{limit}

SELECT job_id, capture_id, zeekad_message_version, zeekad_delivery_mode,
       zeekad_delivery_status, slack_payload, slack_ts, delivered_at, created_at
FROM dashboard.slack_summaries
WHERE capture_id IN
  #{cid}

      AND created_at > #{after}


      AND created_at <= #{until}

ORDER BY created_at DESC, job_id DESC
